import { EventEmitter } from "node:events";
class C { x = 1; inc(): number { this.x += 1; return this.x; } }
class E extends C { y = 2; }
class D { z = 0; }
function main(): void {
  const c = new C(); const e = new E(); const m = new Map<string, number>();
  const ee = new EventEmitter();
  ee.on("c", (o: any) => { o.x = 10; console.log(o === c, o instanceof C, o instanceof D, o === e, c.x, o.inc()); });
  ee.on("e", (o: any) => { o.y = 7; console.log(o === e, o instanceof E, o instanceof C, o instanceof D, e.y); });
  ee.on("m", (o: any) => { o.set("a", 1); console.log(o === m, m.size); });
  ee.on("p", (o: any) => { o.x = 2; console.log(o === c, o instanceof C, o.x); });
  ee.emit("c", c); ee.emit("e", e); ee.emit("m", m); ee.emit("p", { x: 1 });
}
